// Фикстура теста света в стиле Candle: тени, конус, площадной свет, туман.
//
// Сцена подобрана так, чтобы тени было видно ЧИСЛАМИ, а не «на глаз»: фонарь
// слева светит в полный круг радиусом 400, между ним и пробной точкой стоит
// квадрат-препятствие. Точка (400, 300) — в тени этого квадрата, контрольная
// (200, 500) — на том же расстоянии от света, но ничем не заслонена: при
// включении теней она гаснуть не должна.
//
// Камера ставится в центр кадра явно: по умолчанию она в (0, 0), и тогда мир
// уезжает в правый нижний угол, а замеры яркости бьют мимо сцены.
//
// Туман по умолчанию спрятан, чтобы не мешать замеру теней: тест включает его
// отдельным шагом и смотрит, что кадр стал светлее.
$.ready(() => {
    $.camera.at(400, 300);
    $.world.gravity(0, 0).color('#000000').bounds(0, 0, 800, 600);
    $('<rect>', { id: 'base' }).at(400, 300).size(800, 600).color('#000000').appendTo($.world);

    // Препятствие: видимый квадрат и он же — окклюдер для света.
    $('<rect>', { id: 'wall' }).at(300, 300).size(40, 40).color('#2a2f3a').appendTo($.world);
    $.gfx.light.occluders([{ x: 280, y: 280, w: 40, h: 40 }]);

    // Фонарь: конус вправо, тени и полный круг включает тест.
    $('<light>', {
        id: 'lamp', radius: 400, intensity: 1, color: '#ffddaa',
        cone: 140, segments: 64, shadows: false,
    }).at(200, 300).blend('add').appendTo($.world);

    // Площадной свет: проверяем, что тег жив, рисуется и считает тени.
    $('<lightarea>', {
        id: 'area', radius: 150, intensity: 0.9, color: '#88bbff',
        samples: 4, shadows: true,
    }).at(620, 480).size(220, 12).blend('add').appendTo($.world);

    // Туман: узел в мире (спрятан до отдельного шага теста).
    $('<fog>', { id: 'mist', color: '#8899bb', density: 0.4, layers: 4 })
        .at(400, 300).size(800, 600).hide().appendTo($.world);

    // Свет, который прорезает туман: рисуется поверх дымки.
    $('<light>', { id: 'torch', radius: 120, intensity: 1, color: '#ffcc66', punch: true })
        .at(150, 120).blend('add').appendTo($.world);

    // Экранный туман выключен: его включает тест.
    $.gfx.fog.off();
});
